        return tags.Count == 0
            ? null
            : global::ProcessLens.Core.SysPulseLocalization.Capture($"Librerie caricate compatibili con sottosistemi: {(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),tags))} (la presenza della DLL non prova chiamate attive).");
    }

