            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("Node.js è stato avviato con l'entrypoint "), global::ProcessLens.Core.SysPulseLocalization.Literal("Node.js started with entrypoint "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("Il runtime .NET è stato avviato con l'assembly "), global::ProcessLens.Core.SysPulseLocalization.Literal(".NET runtime started with assembly "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("dotnet watch esegue un'applicazione e può riavviarla alla modifica dei sorgenti"), global::ProcessLens.Core.SysPulseLocalization.Literal("dotnet watch runs an application and reloads on source changes"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell è stato avviato con lo script "), global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell started with script "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell ha ricevuto un comando codificato; non è stato eseguito o decodificato dall'analizzatore"), global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell received an encoded command (not decoded or executed by analyzer)"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell esegue un comando passato come parametro, senza esporne il contenuto nel report"), global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell executes a parameter command (content redacted)"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato per inviare dati a un endpoint remoto"), global::ProcessLens.Core.SysPulseLocalization.Literal("curl invoked to upload data to a remote endpoint"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato per richiedere intestazioni HTTP"), global::ProcessLens.Core.SysPulseLocalization.Literal("curl invoked to request HTTP headers"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato come client di rete; il contenuto scambiato e l'esito non sono osservabili"), global::ProcessLens.Core.SysPulseLocalization.Literal("curl invoked as a network client; payload and outcome are not observable"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("ffmpeg è stato avviato per elaborare contenuti multimediali forniti come input"), global::ProcessLens.Core.SysPulseLocalization.Literal("ffmpeg started to process input media streams"), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("Host servizi Windows avviato per il gruppo "), global::ProcessLens.Core.SysPulseLocalization.Literal("Windows Service Host started for group "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("Host componente COM isolato avviato per AppID "), global::ProcessLens.Core.SysPulseLocalization.Literal("Isolated COM Surrogate started for AppID "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("rundll32 è stato avviato con la libreria "), global::ProcessLens.Core.SysPulseLocalization.Literal("rundll32 started with library "), StringComparison.Ordinal)
            .Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("La JVM è stata avviata con l'archivio "), global::ProcessLens.Core.SysPulseLocalization.Literal("JVM started with JAR archive "), StringComparison.Ordinal);
