    private static string? IdentifyOperation(ProcessSnapshot p, List<string> evidence)
    {
        string cmd = p.CommandLine ?? "";
        string name = global::ProcessLens.Core.SysPulseLocalization.Map((p.Name ?? ""),__s=>__s.ToLowerInvariant());
        if ((name is "git" or "git.exe") || name.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("git-remote-"), StringComparison.Ordinal))
        {
            var git = ProcessOriginAnalyzer.Analyze(p);
            if (git.Operation.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("sottocomando non identificabile"), StringComparison.OrdinalIgnoreCase) ||
                git.Operation.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("non determinata"), StringComparison.OrdinalIgnoreCase))
                return null;
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Sottocomando Git ricavato dalla command line del PID o da un antenato con istanza verificata."));
            // The origin analyzer may include a -C working directory: redact it from this report.
            return git.Operation.Split(global::ProcessLens.Core.SysPulseLocalization.Literal(" Directory indicata"), StringSplitOptions.None)[0].TrimEnd('.');
        }
        if (string.IsNullOrWhiteSpace(cmd)) return null;
        if (name.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("python"), StringComparison.Ordinal))
        {
            var module = Regex.Match(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-m\s+([\w.\-]{1,100})(?=\s|$)"));
            if (module.Success) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Opzione Python -m presente nella command line, nome modulo esposto.")); return global::ProcessLens.Core.SysPulseLocalization.Capture($"L'interprete Python è stato avviato con il modulo {(module.Groups[1].Value)}"); }
            var py = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.pyw?"));
            if (py is not null) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Entrypoint .py/.pyw identificato nella command line.")); return global::ProcessLens.Core.SysPulseLocalization.Capture($"Python è stato avviato con lo script {(py)}"); }
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-c(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Opzione -c Python rilevata; contenuto dello script non mostrato.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("Python esegue codice fornito sulla riga di comando, il cui contenuto non viene esposto"); }
        }
        if (name is "node" or "node.exe" or "nodejs" or "nodejs.exe")
        {
            var js = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.(?:js|mjs|cjs|ts)"));
            if (js is not null) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Entrypoint JavaScript/TypeScript osservato nella command line.")); return global::ProcessLens.Core.SysPulseLocalization.Capture($"Node.js è stato avviato con l'entrypoint {(js)}"); }
        }
        if (name is "dotnet" or "dotnet.exe")
        {
            var dll = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.dll"));
            if (dll is not null) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Assembly DLL nella command line dotnet.")); return global::ProcessLens.Core.SysPulseLocalization.Capture($"Il runtime .NET è stato avviato con l'assembly {(dll)}"); }
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)watch\s+run(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Subcomando dotnet watch run osservato.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("dotnet watch esegue un'applicazione e può riavviarla alla modifica dei sorgenti"); }
        }
        if (name is "powershell" or "powershell.exe" or "pwsh" or "pwsh.exe")
        {
            var script = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.ps1"));
            if (script is not null) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Script PS1 individuato nella command line.")); return global::ProcessLens.Core.SysPulseLocalization.Capture($"PowerShell è stato avviato con lo script {(global::ProcessLens.Core.SysPulseLocalization.Opaque(script))}"); }
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-(?:encodedcommand|enc)(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Parametro di codice codificato osservato, non decodificato.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell ha ricevuto un comando codificato; non è stato eseguito o decodificato dall'analizzatore"); }
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-(?:command|c)(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Parametro -Command osservato; contenuto non mostrato.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("PowerShell esegue un comando passato come parametro, senza esporne il contenuto nel report"); }
        }
        if (name is "curl" or "curl.exe")
        {
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)(?:-T|--upload-file)(?:\s|=)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Opzione curl di upload rilevata.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato per inviare dati a un endpoint remoto"); }
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)(?:-I|--head)(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Opzione curl per header HTTP rilevata.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato per richiedere intestazioni HTTP"); }
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Eseguibile curl con command line disponibile; URL non mostrati."));
            return global::ProcessLens.Core.SysPulseLocalization.Literal("curl è stato invocato come client di rete; il contenuto scambiato e l'esito non sono osservabili");
        }
        if ((name is "ffmpeg" or "ffmpeg.exe") && cmd.Length > 0)
        {
            if (Regex.IsMatch(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-i(?:\s|$)"))) { evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Opzione ffmpeg -i rilevata; percorso sorgente nascosto.")); return global::ProcessLens.Core.SysPulseLocalization.Literal("ffmpeg è stato avviato per elaborare contenuti multimediali forniti come input"); }
        }
        if (name is "svchost" or "svchost.exe")
        {
            var svcGroup = Regex.Match(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-k\s+([a-zA-Z0-9_.\-]{1,64})"));
            var svcName = Regex.Match(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)(?:^|\s)-s\s+([a-zA-Z0-9_.\-]{1,64})"));
            if (svcGroup.Success)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Parametri svchost -k/-s osservati nella command line."));
                string suffix = svcName.Success ? global::ProcessLens.Core.SysPulseLocalization.Capture($" (servizio specifico: {(svcName.Groups[1].Value)})") : "";
                return global::ProcessLens.Core.SysPulseLocalization.Capture($"Host servizi Windows avviato per il gruppo {(svcGroup.Groups[1].Value)}{(suffix)}");
            }
        }
        if (name is "dllhost" or "dllhost.exe")
        {
            var clsid = Regex.Match(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"(?i)/processid:\{?([0-9a-fA-F\-]{8,36})\}?"));
            if (clsid.Success)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Parametro COM /Processid osservato nella command line."));
                return global::ProcessLens.Core.SysPulseLocalization.Capture($"Host componente COM isolato avviato per AppID {{{(clsid.Groups[1].Value)}}}");
            }
        }
        if (name is "rundll32" or "rundll32.exe")
        {
            var dll = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.dll"));
            if (dll is not null)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Libreria DLL target osservata nella command line di rundll32."));
                return global::ProcessLens.Core.SysPulseLocalization.Capture($"rundll32 è stato avviato con la libreria {(dll)}");
            }
        }
        if (name is "java" or "java.exe" or "javaw" or "javaw.exe")
        {
            var jar = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.jar"));
            if (jar is not null)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Archivio .jar osservato nella command line JVM."));
                return global::ProcessLens.Core.SysPulseLocalization.Capture($"La JVM è stata avviata con l'archivio {(jar)}");
            }
        }
        if (name is "msbuild" or "msbuild.exe")
        {
            var proj = FileNameFromCommand(cmd, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\.(?:sln|csproj|vbproj|vcxproj)"));
            if (proj is not null)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("File di progetto/soluzione osservato nella command line MSBuild."));
                return global::ProcessLens.Core.SysPulseLocalization.Capture($"MSBuild è stato avviato per il progetto {(proj)}");
            }
        }
        return null;
    }

    private static string? FileNameFromCommand(string command, string suffix)
    {
        // Capture only an entrypoint basename, never the full path or arbitrary arguments.
        string pattern = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("(?i)(?:^|\\s)(?:\\\"([^\\\"]+"),suffix),global::ProcessLens.Core.SysPulseLocalization.Literal(")\\\"|([^\\s\\\"]+")),suffix),global::ProcessLens.Core.SysPulseLocalization.Literal("))(?=\\s|$)"));
        var match = Regex.Match(command, pattern);
        if (!match.Success) return null;
        string value = (match.Groups[1].Success ? match.Groups[1].Value : match.Groups[2].Value).Replace('\\', '/');
        string file = value[(value.LastIndexOf('/') + 1)..];
        return file.Length is > 0 and <= 120 ? file : null;
    }

    private static string Clean(string? text)
    {
        // Keep text bounded and single-line, since version info is untrusted input.
        return string.IsNullOrWhiteSpace(text) ? global::ProcessLens.Core.SysPulseLocalization.Literal("non disponibile") :
            new string(global::ProcessLens.Core.SysPulseLocalization.Map(text,__s=>__s.Trim()).Where(c => !char.IsControl(c)).Take(140).ToArray());
    }
